INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31565, 0, 0, 'Welcome to my kingdom of darkness!', 14, 0, 100, 1, 0, 16156, 32375, 0, 'Varimathras - Battle for the Undercity'),
(31565, 1, 0, 'Did you enjoy my minion''s terrible creation? Potent, is it not?', 14, 0, 100, 1, 0, 16157, 32376, 0, 'Varimathras - Battle for the Undercity'),
(31565, 2, 0, 'But enough prattling! You wish to reclaim your city? Come then, heroes! Your souls will fuel the host! You will have this place back in pieces!', 14, 0, 100, 1, 0, 16158, 32383, 0, 'Varimathras - Battle for the Undercity'),
(31565, 3, 0, 'Clever girl...', 14, 0, 100, 1, 0, 16159, 32521, 0, 'Varimathras - Battle for the Undercity'),
(31565, 4, 0, 'My brothers have grown hungry. Your souls will sate their appetites.', 14, 0, 100, 1, 0, 16160, 32524, 0, 'Varimathras - Battle for the Undercity'),
(31565, 5, 0, 'Bring down the halls! NOW!', 14, 0, 100, 1, 0, 16161, 32568, 0, 'Varimathras - Battle for the Undercity'),
(31565, 6, 0, 'Welcome to your future -- what little there is left of it...', 14, 0, 100, 1, 0, 16163, 32580, 0, 'Varimathras - Battle for the Undercity'),
(31565, 7, 0, 'Too long... Tireless, endless planning... It will not end like this...', 14, 0, 100, 1, 0, 16164, 32610, 0, 'Varimathras - Battle for the Undercity'),
(31565, 8, 0, 'Need more time... The Master is near...', 14, 0, 100, 1, 0, 16165, 32611, 0, 'Varimathras - Battle for the Undercity'),
(31565, 9, 0, 'Such power! Can you not feel it, mortals? Cease this foolishness and join me!', 14, 0, 100, 1, 0, 16166, 32612, 0, 'Varimathras - Battle for the Undercity'),
(31565, 10, 0, 'I will not fail!', 14, 0, 100, 1, 0, 16167, 39424, 0, 'Varimathras - Battle for the Undercity'),
(31565, 11, 0, 'I cannot hold... Destabilizing...', 14, 0, 100, 1, 0, 16168, 32614, 0, 'Varimathras - Battle for the Undercity'),
(31565, 12, 0, 'A thousand-thousand pardons, Master! I will deal with these intruders myself!', 14, 0, 100, 1, 0, 16162, 32579, 0, 'Varimathras - Battle for the Undercity'),
(31565, 13, 0, 'Years... wasted...', 14, 0, 100, 1, 0, 16169, 32617, 0, 'Varimathras - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31739, 0, 0, 'We''ll burn it to the ground before giving it to you!', 14, 0, 100, 0, 0, 0, 32330, 0, 'Warsong Battleguard - Battle for the Undercity'),
(31739, 1, 0, 'That wretch Putress won''t get away with this!', 12, 0, 100, 0, 0, 0, 32266, 0, 'Warsong Battleguard - Battle for the Undercity'),
(31739, 2, 0, 'For the Horde!', 14, 0, 100, 0, 0, 0, 4921, 0, 'Warsong Battleguard - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31844, 0, 0, 'YAAAAAAAARGGGGHHHHH!!!!', 14, 0, 100, 0, 0, 0, 32437, 0, 'Blight Aberration - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32277, 0, 0, 'YOU HAVE FAILED ME, VARIMATHRAS!', 14, 0, 100, 0, 0, 16180, 32618, 0, 'A distant voice - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32315, 0, 0, 'I know what he would do.', 12, 0, 100, 0, 0, 16286, 32731, 0, 'High Overlord Saurfang - Battle for the Undercity'),
(32315, 1, 0, 'He would say to you: Thrall. Lead your people.', 12, 0, 100, 0, 0, 16287, 32732, 0, 'High Overlord Saurfang - Battle for the Undercity'),
(32315, 2, 0, 'Let''s go home, old friend.', 12, 0, 100, 0, 0, 16288, 32733, 0, 'High Overlord Saurfang - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32365, 0, 0, '%s begins to dance.', 16, 0, 100, 1, 0, 0, 1480, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 1, 0, 'The shaft is trapped, Warchief. A fall would mean certain death.', 12, 0, 100, 1, 0, 16300, 32462, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 2, 0, 'What have they done to my beautiful city!', 12, 0, 100, 1, 0, 16301, 32489, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 3, 0, 'The only redemption for the traitors responsible for this will be an agonizing death. My vengeance will be swift and without mercy.', 12, 0, 100, 1, 0, 16302, 32495, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 4, 0, 'Very well, Warchief. The Royal Quarter is this way. Stay on guard. There is no telling what Varimathras and Putress have in store for us.', 12, 0, 100, 1, 0, 16303, 32497, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 5, 0, 'HOLD! I sense dark magic. Demon magic... Stand ready!', 12, 0, 100, 1, 0, 16304, 32520, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 6, 0, 'The Royal Quarter is just up ahead, Warchief.', 12, 0, 100, 1, 0, 16305, 32567, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(32365, 7, 0, 'Such will be the fate of all enemies of the Horde, Warchief.  Now we must deal with the wretch, Putress.', 12, 0, 100, 1, 0, 16306, 32647, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32511, 0, 0, 'No hope for you!', 11, 0, 100, 0, 0, 0, 32545, 0, 'Khanok the Impassable - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32518, 2, 0, 'HEROES OF THE HORDE, YOUR WARCHIEF CALLS!', 14, 0, 100, 1, 0, 16187, 32339, 0, 'Thrall - Battle for the Undercity'),
(32518, 3, 0, 'Gather behind me at the gates of the Undercity! Soon we march upon our fallen city and reclaim it - FOR THE HORDE!', 14, 0, 100, 1, 0, 16188, 32361, 0, 'Thrall - Battle for the Undercity'),
(32518, 4, 0, 'Blood and thunder, champions of the Horde! We fight on this day for our fallen brothers and sisters! Mourn them not for they all died with honor in their hearts!', 14, 0, 100, 1, 0, 16189, 32340, 0, 'Thrall - Battle for the Undercity'),
(32518, 5, 0, 'Though we face great conflict, our might combined shall obliterate those who would oppose us! The grave injustices committed against the Horde will be met by an unstoppable force of reckoning!', 14, 0, 100, 1, 0, 16190, 32341, 0, 'Thrall - Battle for the Undercity'),
(32518, 6, 0, 'I call to you great spirits! Grant the Horde your blessing! For on this day our cause is righteous and just!', 14, 0, 100, 1, 0, 16191, 32342, 0, 'Thrall - Battle for the Undercity'),
(32518, 7, 0, 'Spirits of wind, carry to Saurfang the Younger the song of war! May ALL of our fallen brethren be vindicated by this battle!\n', 14, 0, 100, 1, 0, 16192, 32362, 0, 'Thrall - Battle for the Undercity'),
(32518, 8, 0, 'The battle for the Undercity begins now! Sound the horns of war! Champions of the Horde, be empowered by the might of your Warchief!', 14, 0, 100, 1, 0, 16193, 32363, 0, 'Thrall - Battle for the Undercity'),
(32518, 9, 0, 'ONWARD!', 14, 0, 100, 1, 0, 16195, 32366, 0, 'Thrall - Battle for the Undercity'),
(32518, 10, 0, 'Great wind brother, clear our path!', 14, 0, 100, 1, 0, 16196, 32367, 0, 'Thrall - Battle for the Undercity'),
(32518, 11, 0, 'You must answer to the elements, demon!', 14, 0, 100, 1, 0, 16197, 32368, 0, 'Thrall - Battle for the Undercity'),
(32518, 12, 0, 'Great water spirit, wash away this corruption!', 12, 0, 100, 1, 0, 16194, 32369, 0, 'Thrall - Battle for the Undercity'),
(32518, 13, 0, 'ATTACK!!!!', 14, 0, 100, 1, 0, 16198, 32396, 0, 'Thrall - Battle for the Undercity'),
(32518, 14, 0, 'The courtyard is ours! Onward to the inner sanctum!', 14, 0, 100, 1, 0, 16199, 32460, 0, 'Thrall - Battle for the Undercity'),
(32518, 15, 0, 'HOLD! They''ve destroyed the elevator!', 12, 0, 100, 1, 0, 16200, 32461, 0, 'Thrall - Battle for the Undercity'),
(32518, 16, 0, 'Great air spirit, hear my call once more!', 12, 0, 100, 1, 0, 16201, 32490, 0, 'Thrall - Battle for the Undercity'),
(32518, 17, 0, 'The spirits of air have heard my call. Cyclones will lower us to safety. Now we jump!', 12, 0, 100, 1, 0, 16202, 32491, 0, 'Thrall - Battle for the Undercity'),
(32518, 18, 0, 'We have breached the inner sanctum, heroes! We press on!', 14, 0, 100, 1, 0, 16203, 32494, 0, 'Thrall - Battle for the Undercity'),
(32518, 19, 0, 'Lead the way, Dark Lady. We will follow.', 12, 0, 100, 1, 0, 16204, 32496, 0, 'Thrall - Battle for the Undercity'),
(32518, 20, 0, 'Is that all, demon? Have you nothing left to throw at us?', 14, 0, 100, 1, 0, 16205, 32553, 0, 'Thrall - Battle for the Undercity'),
(32518, 21, 0, 'We come for you! Prepare yourself!', 14, 0, 100, 1, 0, 16206, 32564, 0, 'Thrall - Battle for the Undercity'),
(32518, 22, 0, 'COWARD! You think to stop the Warchief of the Horde with pebbles? I will show you the true power of the elements!', 14, 0, 100, 1, 0, 16207, 32565, 0, 'Thrall - Battle for the Undercity'),
(32518, 23, 0, 'Great spirits of the earth, help us in our hour of need!', 14, 0, 100, 1, 0, 16208, 32575, 0, 'Thrall - Battle for the Undercity'),
(32518, 24, 0, 'LET''S GO! QUICKLY!', 14, 0, 100, 1, 0, 16210, 32583, 0, 'Thrall - Battle for the Undercity'),
(32518, 25, 0, 'What is this?', 14, 0, 100, 1, 0, 16211, 13820, 0, 'Thrall - Battle for the Undercity'),
(32518, 26, 0, 'WE ARE VICTORIOUS!', 14, 0, 100, 1, 0, 16212, 32643, 0, 'Thrall - Battle for the Undercity'),
(32518, 27, 0, 'The Undercity belongs to the Horde once more! LOK''TAR!', 14, 0, 100, 1, 0, 16214, 32644, 0, 'Thrall - Battle for the Undercity'),
(32518, 28, 0, 'Dark Lady, join me! You have fought hard and spilled much blood for this right. The Royal Quarter belongs to you!', 12, 0, 100, 1, 0, 16215, 32646, 0, 'Thrall - Battle for the Undercity'),
(32518, 29, 0, 'We shall, Sylvanas...', 12, 0, 100, 1, 0, 16216, 32648, 0, 'Thrall - Battle for the Undercity'),
(32518, 30, 0, 'Alliance horns? Stay on guard!', 12, 0, 100, 1, 0, 16217, 32649, 0, 'Thrall - Battle for the Undercity'),
(32518, 31, 0, 'It ends like it began...', 12, 0, 100, 1, 0, 16218, 32728, 0, 'Thrall - Battle for the Undercity'),
(32518, 32, 0, 'All that we have fought for in this world is lost. The hopes and dreams carried by my father and mother... by Doomhammer... Gone...', 12, 0, 100, 1, 0, 16219, 32729, 0, 'Thrall - Battle for the Undercity'),
(32518, 33, 0, 'If only you were here right now, old friend. You would know what to do.', 12, 0, 100, 1, 0, 16220, 32730, 0, 'Thrall - Battle for the Undercity'),
(32518, 34, 0, '%s nods.', 16, 0, 100, 1, 0, 0, 3065, 0, 'Thrall - Battle for the Undercity'),
(32518, 35, 0, 'It''s good to have you back, Varok, old friend. I''m sorry about your boy.', 12, 0, 100, 1, 0, 16221, 32735, 0, 'Thrall - Battle for the Undercity');
