INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31530, 0, 0, 'Do not let them pass, minions!', 14, 0, 100, 0, 0, 16289, 32943, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 1, 0, 'KILL THEM! My work must not be interrupted!', 14, 0, 100, 0, 0, 16290, 32944, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 2, 0, 'Stare into the abyss and watch as it blackens your souls!', 14, 0, 100, 0, 0, 16294, 32949, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 3, 0, 'You are no match for my creations!', 14, 0, 100, 0, 0, 16295, 32952, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 4, 0, 'This cannot be happening!', 14, 0, 100, 0, 0, 16296, 32953, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 5, 0, 'It will not end like this! I''ve worked too hard! So many years... I... I will consume more energy!', 14, 0, 100, 0, 0, 16291, 32948, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 6, 0, 'The power washes through me! I see... EVERYTHING!', 14, 0, 100, 0, 0, 16292, 32950, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 7, 0, 'MORE SUFFERING AWAITS!', 14, 0, 100, 0, 0, 16293, 32951, 0, 'Grand Apothecary Putress - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32401, 0, 0, 'Heroes of the Alliance, your King calls! Gather behind me at the entrance to the sewers!', 14, 0, 100, 1, 0, 16103, 32843, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 1, 0, 'Hidden inside this defiled city is the wretch responsible for murdering our brothers and sisters at the Wrathgate! He must be brought to justice!', 14, 0, 100, 1, 0, 16104, 32979, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 2, 0, 'Soon we will march upon this cursed place and cleanse it of its evil!', 14, 0, 100, 1, 0, 16102, 32844, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 3, 0, 'The hour of redemption is close at hand! Prepare yourselves!', 14, 0, 100, 1, 0, 16101, 32847, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 4, 0, 'The march upon the Undercity begins now! Be empowered by your King''s strength! Follow me, heroes! FOR THE GLORY OF THE ALLIANCE!', 14, 0, 100, 1, 0, 16100, 32849, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 5, 0, 'Onward, brothers and sisters! Destiny awaits!', 14, 0, 100, 1, 0, 16079, 32856, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 6, 0, 'Our descent into the depths of depravity begins! Be on guard! Jaina, lend us your strength!', 12, 0, 100, 1, 0, 16080, 32858, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 7, 0, 'Hold the barricades!  Do not give them an inch!', 12, 0, 100, 1, 0, 16081, 36090, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 8, 0, 'Soldiers, fall in! Guard the halls!', 14, 0, 100, 1, 0, 16082, 32938, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 9, 0, 'Your aberrations are no match for the Alliance, Putress! We''re coming for you!', 14, 0, 100, 1, 0, 16083, 32937, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 10, 0, 'Horde. By the looks of the struggle, they are here in force - somewhere.', 12, 0, 100, 1, 0, 16084, 32940, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 11, 0, 'Stay alert and on guard. There''s no telling what horrors await us.', 12, 0, 100, 1, 0, 16085, 32941, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 12, 0, 'ONWARD!', 12, 0, 100, 1, 0, 16086, 12821, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 13, 0, 'The main chamber is this way! Let''s go!', 12, 0, 100, 1, 0, 16087, 32945, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 14, 0, 'There! There!', 12, 0, 100, 1, 0, 16088, 24654, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 15, 0, 'There''s nowhere to run, monster!', 14, 0, 100, 1, 0, 16089, 32947, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 16, 0, 'And justice is served!', 14, 0, 100, 1, 0, 16090, 32961, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 17, 0, 'What say you now, Putress?', 12, 0, 100, 1, 0, 16091, 32962, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 18, 0, 'Look around you, brothers and sisters. Open your eyes! Look at what they have done to our kingdom!', 12, 0, 100, 1, 0, 16092, 32963, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 19, 0, 'How much longer will we allow these savages free reign in our world?', 12, 0, 100, 1, 0, 16093, 32964, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 20, 0, 'I have seen the Horde''s world. I have been inside their cities. Inside their minds...', 12, 0, 100, 1, 0, 16094, 32965, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 21, 0, 'I know what evil lies in the hearts of orcs.', 12, 0, 100, 1, 0, 16095, 32966, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 22, 0, 'THRALL! HERE?', 12, 0, 100, 1, 0, 16096, 32968, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 23, 0, 'ONWARD! We end this now!', 12, 0, 100, 1, 0, 16097, 32969, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 24, 0, 'You should all know, the orcs have a battle cry: LOK''TAR OGAR! It means "victory or death." Fitting...', 12, 0, 100, 1, 0, 16098, 32970, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 25, 0, 'To the throne room!', 12, 0, 100, 1, 0, 16099, 32971, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 26, 0, 'I was away for too long. My absence cost us the lives of some of our greatest heroes. Trash like you and this evil witch were allowed to roam free -- unchecked.', 12, 0, 100, 1, 0, 16073, 32691, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 27, 0, 'The time has come to make things right. To disband your treacherous kingdom of murderers and thieves. Putress was the first strike. Many more will come.', 12, 0, 100, 1, 0, 16074, 32693, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 28, 0, 'I''ve waited a long time for this, Thrall. For every time I was thrown into one of your damned arenas... for every time I killed a green-skinned aberration like you... I could think of only one thing.', 12, 0, 100, 1, 0, 16075, 32697, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 29, 0, 'What our world could be without you and your twisted Horde... It ends now, Warchief.', 12, 0, 100, 1, 0, 16076, 32699, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 30, 0, 'ATTACK! FOR STORMWIND! FOR BOLVAR! FOR THE ALLIANCE!', 12, 0, 100, 1, 0, 16077, 32700, 0, 'King Varian Wrynn - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32402, 0, 0, 'Right away, your majesty!', 12, 0, 100, 1, 0, 16126, 32865, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 1, 0, 'What''s happened here? There are corpses everywhere... the stench... overwhelming...', 12, 0, 100, 1, 0, 16127, 32939, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 2, 0, 'Varian, stop! I won''t help you do this!', 12, 0, 100, 1, 0, 16128, 32972, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 3, 0, 'VARIAN, NO! STOP!', 14, 0, 100, 1, 0, 16122, 32709, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 4, 0, 'It did not have to be like this...', 12, 0, 100, 1, 0, 16123, 32711, 0, 'Lady Jaina Proudmoore - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32518, 0, 0, 'WE ARE VICTORIOUS!', 12, 0, 100, 1, 0, 16212, 32643, 0, 'Thrall - Battle for the Undercity'),
(32518, 1, 0, 'The Undercity belongs to the Horde once more! LOK''TAR!', 12, 0, 100, 1, 0, 16214, 32644, 0, 'Thrall - Battle for the Undercity');
